package local.morph.wgtcheck;
import android.app.*;import android.os.*;import java.io.*;import java.util.zip.*;import java.lang.reflect.*;import java.security.cert.*;
public final class WgtArchiveInstrumentation extends Instrumentation{
 void check(boolean v,String m){if(!v)throw new AssertionError(m);}byte[] archive(String extra)throws Exception{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(bytes)){z.putNextEntry(new ZipEntry("config.xml"));z.write(("<widget xmlns='http://www.w3.org/ns/widgets' xmlns:t='http://tizen.org/ns/widgets' version='1.0'><t:application id='fixture001.App' package='fixture001'/><t:profile name='tv-samsung'/><name>Owned Android import fixture</name>"+extra+"</widget>").getBytes("UTF-8"));z.closeEntry();z.putNextEntry(new ZipEntry("index.html"));z.write("Owned import test".getBytes("UTF-8"));z.closeEntry();}return bytes.toByteArray();}
 @Override public void onCreate(Bundle a){super.onCreate(a);start();}
 @Override public void onStart(){Bundle out=new Bundle();try{Class<?> type=Class.forName("local.cleartv.mobile.SamsungWidget",true,getTargetContext().getClassLoader());Method read=type.getDeclaredMethod("read",InputStream.class);read.setAccessible(true);Field level=type.getDeclaredField("level");level.setAccessible(true);Method info=type.getDeclaredMethod("info");info.setAccessible(true);
 Object normal=read.invoke(null,new ByteArrayInputStream(archive("")));check(level.get(normal).equals("public"),"Android parser selects Public");check(((org.json.JSONObject)info.invoke(normal)).getString("appId").equals("fixture001.App"),"Android preview exposes manifest identity");Object partner=read.invoke(null,new ByteArrayInputStream(archive("<t:privilege name='http://tizen.org/privilege/vpnservice'/>")));check(level.get(partner).equals("partner"),"Android parser selects Partner");
 for(String file:new String[]{"ca-author.cer","ca-distributor.crt","ca-distributor-partner.crt"})try(InputStream in=getTargetContext().getAssets().open(file)){((X509Certificate)CertificateFactory.getInstance("X.509").generateCertificate(in)).checkValidity();}
 out.putString("result","PASS Android WGT import: real manifest parser, preview identity, Public/Partner selection and all bundled Samsung CA certificates. No Samsung network or TV install was performed.");finish(Activity.RESULT_OK,out);
 }catch(Throwable e){out.putString("error",android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,out);}}
}
